import{_ as o,c as r,o as t,j as e,ag as i,a as s}from"./chunks/framework.DZ_cNctr.js";const f=JSON.parse('{"title":"Local Files","description":"Open OME-Zarr data straight from your disk in Chrome or Edge. The viewer reads the folder where it sits, so there is nothing to upload and nothing to copy.","frontmatter":{"title":"Local Files","description":"Open OME-Zarr data straight from your disk in Chrome or Edge. The viewer reads the folder where it sits, so there is nothing to upload and nothing to copy."},"headers":[],"relativePath":"guides/local-files.md","filePath":"guides/local-files.md"}'),l={name:"guides/local-files.md"};function n(d,a,h,c,p,u){return t(),r("div",null,[...a[0]||(a[0]=[e("h1",{id:"local-files",tabindex:"-1"},[s("Local Files "),e("a",{class:"header-anchor",href:"#local-files","aria-label":'Permalink to "Local Files"'},"​")],-1),e("p",null,"Open OME-ZARR data from your local disk without uploading anything.",-1),e("div",{style:{position:"relative","padding-bottom":"56.25%",height:"0",overflow:"hidden",margin:"1.5rem 0"}},[e("iframe",{src:"https://www.youtube.com/embed/p9veMmibuWA?rel=0&modestbranding=1&vq=hd720&mute=1",title:"Open Your Microscopy Data in 10 Seconds",style:{position:"absolute",top:"0",left:"0",width:"100%",height:"100%",border:"0"},allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""})],-1),i('<p>Reading from disk is the fastest and most private way to work, but it is not the only one. <a href="https://www.find-nuclei.com/blog/local-vs-remote-ome-zarr" target="_blank" rel="noreferrer">Your OME-ZARR Storage Setup Is Slowing You Down</a> compares this with streaming from a server, and is worth reading before a lab or facility commits to one setup.</p><h2 id="which-browsers-can-do-this" tabindex="-1">Which Browsers Can Do This <a class="header-anchor" href="#which-browsers-can-do-this" aria-label="Permalink to &quot;Which Browsers Can Do This&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Chrome and Edge only</p><p>Reading a folder from disk needs the File System Access API, which ships in Chrome and Edge and nowhere else. <strong>Both</strong> routes below depend on it: the folder picker and drag and drop alike.</p><p><strong>Firefox and Safari cannot open local folders at all.</strong> Neither can any browser on iOS or iPadOS, because they all run on WebKit.</p><p>In those browsers, serve your data over HTTP and open it by address instead. See <a href="./remote-urls.html">Remote URLs</a> for how, including the free <a href="./data-server.html">Data Server</a> that puts a folder on your own machine behind a local URL in one command. Everything else in the viewer works the same way from there.</p></div><h2 id="drag-and-drop" tabindex="-1">Drag and Drop <a class="header-anchor" href="#drag-and-drop" aria-label="Permalink to &quot;Drag and Drop&quot;">​</a></h2><p>The simplest way to open local data is drag and drop:</p><ol><li>Open <a href="https://find-nuclei.github.io" target="_blank" rel="noreferrer">Find Nuclei Viewer</a> in Chrome or Edge</li><li>Drag your <code>.ome.zarr</code> folder from Finder/Explorer onto the browser</li><li>Drop it. The viewer opens immediately</li></ol><h2 id="using-the-file-picker" tabindex="-1">Using the File Picker <a class="header-anchor" href="#using-the-file-picker" aria-label="Permalink to &quot;Using the File Picker&quot;">​</a></h2><p>Or use the built-in folder picker:</p><ol><li>Click <strong>Open Image</strong> on the landing page</li><li>Click <strong>Open Folder</strong> in the Load Data modal</li><li>Select your <code>.ome.zarr</code> folder</li><li>The viewer loads your data</li></ol><h2 id="if-the-folder-holds-datasets" tabindex="-1">If the Folder Holds Datasets <a class="header-anchor" href="#if-the-folder-holds-datasets" aria-label="Permalink to &quot;If the Folder Holds Datasets&quot;">​</a></h2><p>Data rarely sits on disk as one lonely dataset. Open a folder that holds several and the viewer says so, lists what it found, and opens whichever one you pick:</p><ol><li>Drop the folder, or choose it in the picker, as usual</li><li>The viewer reads each folder inside it to see which are datasets</li><li>Pick one from the list and it opens</li></ol><p>The names in that list come from the data, not from the folder names. A dataset called <code>plate-3</code> or <code>run-2024-05</code> is found just as readily as one called <code>sample.ome.zarr</code>.</p><p>Nothing is uploaded to work this out. The viewer reads a few hundred bytes of metadata from each folder, on your machine, exactly as it reads the dataset itself.</p><h2 id="privacy" tabindex="-1">Privacy <a class="header-anchor" href="#privacy" aria-label="Permalink to &quot;Privacy&quot;">​</a></h2><p>Your data stays entirely on your machine. Find Nuclei Viewer processes everything locally in the browser. No files are uploaded to any server.</p><h2 id="recent-images" tabindex="-1">Recent Images <a class="header-anchor" href="#recent-images" aria-label="Permalink to &quot;Recent Images&quot;">​</a></h2><p>After opening a dataset, it appears in your <strong>Recently Opened</strong> list on the landing page. Click any recent image to reopen it instantly. Thumbnails and metadata are cached in your browser&#39;s local storage.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./remote-urls.html">Remote URLs</a>: the route that works in every browser, and the one to use if yours is not Chrome or Edge</li><li><a href="./data-server.html">Data Server</a>: serve a folder from your own machine over HTTP, so local data opens anywhere</li></ul>',20)])])}const g=o(l,[["render",n]]);export{f as __pageData,g as default};
